-- ---------------------------------------------------------------
-- V1: users of the platform.
-- Never edit this file after it ran; add V2__..., V3__... for changes.
-- Credentials (password hash etc.) are added in the security phase, in a
-- separate table, so the profile data here stays free of secrets.
-- ---------------------------------------------------------------
CREATE TABLE users
(
    -- UUID generated by the application; other services store it as the user reference
    id           VARCHAR(36)  NOT NULL,
    -- Stored lower-case; unique across ALL users, including deleted ones
    email        VARCHAR(254) NOT NULL,
    first_name   VARCHAR(100) NOT NULL,
    last_name    VARCHAR(100) NOT NULL,
    -- E.164 format, e.g. +919876543210
    phone_number VARCHAR(16)  NULL,
    status       VARCHAR(20)  NOT NULL,
    version      BIGINT       NOT NULL DEFAULT 0,
    created_at   DATETIME(6)  NOT NULL,
    updated_at   DATETIME(6)  NOT NULL,
    -- Set when the user is (soft) deleted; the row is kept for order history
    deleted_at   DATETIME(6)  NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DELETED')),
    CONSTRAINT ck_users_deleted CHECK ((status = 'DELETED') = (deleted_at IS NOT NULL))
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;

-- Supports the most common list queries: filter by status, sort by name or date
CREATE INDEX idx_users_status_created ON users (status, created_at);
CREATE INDEX idx_users_last_name ON users (last_name);
